  -webkit-mask-position: center;

  background-image: none !important;
  background-color: var(--top-menu-color) !important;
  width: 24px !important;
  height: 24px !important;
  transform: translate(var(--top-menu-x, 0px), var(--top-menu-y, 0px)) !important;
}

:root {
