.send-btn-custom::after {
  content: "发送";
    color: var(--send-text-color) !important;  /* 改成变量 */
  font-size: 13px;
  font-weight: 500;
}

/* =================================== */
/* 核心逻辑：右侧整体贴底，并且打字时自动藏掉假发送键 */
.input-btns-right {
