/* ============================================================
   模块 E6：表情反应徽章 —— 极简磨砂小胶囊
   ============================================================ */

:root {
  --reaction-badge-bg: rgba(255, 255, 255, 0.75) !important; /* 半透白磨砂底 */
  --reaction-badge-color: inherit !important;
  --reaction-badge-border: 1px solid rgba(255, 255, 255, 0.9) !important; /* 水滴高光边 */
  --reaction-badge-radius: 99px !important; /* 胶囊圆角 */
  --reaction-badge-padding: 2px 6px !important;
  --reaction-badge-size: 13px !important; /* 稍微调大一点点 emoji */
  --reaction-badge-shadow: 0 2px 6px rgba(0, 0, 0, 0.08) !important; /* 浮起来的微影 */
  --reaction-badge-bottom: -12px !important; /* 露出气泡一点点 */
  --reaction-badge-offset: -6px !important; 
}

/* 多重保险：防止原本带有黑底或奇怪的样式 */
.msg-reaction-badge {
  -webkit-backdrop-filter: blur(8px) saturate(150%) !important;
  backdrop-filter: blur(8px) saturate(150%) !important;
  box-shadow: var(--reaction-badge-shadow) !important;
  border: var(--reaction-badge-border) !important;
  background: var(--reaction-badge-bg) !important;
  display: inline-flex !important;
  align-items: center !important;
}

/* 让多个 emoji 之间有一点空隙 */
.msg-reaction-emoji {
  margin: 0 1px !important;
}
/* ============================================================
   模块 L：旁白消息 —— 极简无底色
   ============================================================ */

:root {
  --narration-color: #888888 !important; /* 淡灰色，降低存在感 */
  --narration-size: 13px !important;     /* 字号稍微缩小一点 */
  --narration-style: italic !important;  /* 保留斜体 */
  --narration-bg: transparent !important; /* 透明无底色 */
  --narration-border: none !important;
  --narration-shadow: none !important;
  --narration-padding: 8px 16px !important;
  --narration-margin: 12px 0 !important;
  --narration-max-width: 85% !important;
}
/* ============================================================
   模块 F：居中时间戳 —— 毛玻璃小胶囊
   ============================================================ */

/* 1. 将时间戳变成毛玻璃胶囊 */
.timestamp-custom {
  background: rgba(255, 255, 255, 0.55) !important; /* 半透明白底 */
  -webkit-backdrop-filter: blur(12px) saturate(160%) !important;
  backdrop-filter: blur(12px) saturate(160%) !important;

  border: 1px solid rgba(255, 255, 255, 0.85) !important; /* 水滴高光边 */
  border-radius: 99px !important; /* 胶囊圆角 */

  box-shadow: 
    inset 0 1px 2px rgba(255, 255, 255, 0.9),
    0 2px 8px rgba(0, 0, 0, 0.04) !important; /* 微微浮起的阴影 */

  color: #555555 !important; /* 深灰色文字 */
  font-size: 11px !important;
  font-weight: 600 !important;

  /* 调整胶囊的宽高和居中 */
  padding: 4px 14px !important;
  display: inline-block !important;
  margin: 12px auto !important;
  width: fit-content !important;
}

/* 2. 确保它的父容器是居中的 */
.msg-time-marker {
  display: flex !important;
  justify-content: center !important;
  width: 100% !important;
  margin: 10px 0 !important;
}
/* 强制居中修复 */
.timestamp-custom {
  /* 如果原本是块级，用 flex 让它在父级里居中 */
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  text-align: center !important;

  /* 利用 margin 自动左右居中 */
  margin-left: auto !important;
  margin-right: auto !important;

  /* 或者直接绝对定位居中（二选一，如果上面的不行，用下面三行） */
  /* position: absolute !important; */
  /* left: 50% !important; */
  /* transform: translateX(-50%) !important; */
}

/* 如果它外面还有一层容器限制了它，把外层也居中 */
.msg-time-marker,
[class*="timestamp-container"] {
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  width: 100% !important;
}
