/* ============================================================
   AI 打字指示器 —— 隐藏三点气泡，换成“正在输入中”提示
   ============================================================ */

/* 1. 彻底隐藏原本的三个点气泡 */
.nuo-typing-indicator .nuo-typing-bubble {
  display: none !important;
}

/* 2. 在原本气泡的位置，用伪元素生成一个极简的文字提示 */
.nuo-typing-indicator::after {
  content: "对方正在输入中..." !important;
  display: inline-block !important;

  /* 黑白水滴胶囊质感 */
  background: rgba(255, 255, 255, 0.6) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  backdrop-filter: blur(10px) !important;
  border: 1px solid rgba(255, 255, 255, 0.8) !important;
  border-radius: 12px !important;
  padding: 6px 12px !important;
  margin-top: 4px !important;

  /* 文字样式 */
  color: #888888 !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  letter-spacing: 0.5px !important;

  /* 确保它对齐 */
  box-shadow: inset 0 1px 2px rgba(255,255,255,0.8) !important;
}

/* 3. 确保外层容器的对齐 */
.nuo-typing-indicator {
  display: flex !important;
  align-items: center !important;
  margin-left: 14px !important; /* 和对方气泡对齐 */
}
/* ============================================================
   绝杀：用 :has() 让顶栏备注在打字时变文字
   ============================================================ */

/* 1. 只要聊天区域里有打字指示器，就把顶栏原本的备注隐藏 */
.chat-detail-screen:has(.nuo-typing-indicator) .chat-header-title {
    color: transparent !important;
    font-size: 0 !important;
}

/* 2. 在顶栏备注原来的位置，用伪元素写上新文字 */
.chat-detail-screen:has(.nuo-typing-indicator) .chat-header-title::after {
    content: "对方正在输入中..." !important;
    display: inline-block !important;
    color: #888888 !important; /* 灰色字 */
    font-size: 14px !important; /* 调整字号 */
    font-weight: 600 !important;
    letter-spacing: 0.5px !important;
}

/* 3. 顺便把顶栏原本的副标题（Instagram · 助手）也藏起来，不然会重叠 */
.chat-detail-screen:has(.nuo-typing-indicator) .chat-header-subtitle {
    display: none !important;
}
/* ============================================================
   AI 打字提示：底部彻底隐藏，顶部备注完美替换（纯黑版）
   ============================================================ */

/* 1. 彻底隐藏底部的打字气泡 */
.nuo-typing-indicator {
    display: none !important;
}

/* 2. 隐藏顶栏原本的备注 */
.chat-detail-screen:has(.nuo-typing-indicator) .chat-header-title {
    color: transparent !important;
    font-size: 0 !important;
}

/* 3. 变出“对方正在输入中” —— 纯黑 */
.chat-detail-screen:has(.nuo-typing-indicator) .chat-header-title::after {
    content: "对方正在输入中..." !important;
    display: inline-block !important;
    color: #000000 !important; /* 👈 改成了纯黑，和你的顶栏名字一样黑 */
    font-size: 14px !important; 
    font-weight: 600 !important;
    letter-spacing: 0.5px !important;
}

/* 4. 隐藏顶栏原本的副标题 */
.chat-detail-screen:has(.nuo-typing-indicator) .chat-header-subtitle {
    display: none !important;
}
